"""run.py — 以"不碰既有文件"的方式启动 voice_agent, 并挂上快路径钩子

用法:
  set OPENCODE_FASTPATH=shadow   # 只记录(默认推荐)
  set OPENCODE_FASTPATH=live     # 允许接管 additive 条目
  python -m opencode_fastpath.run [voice_agent 原有参数...]
"""
from __future__ import annotations

import os
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
ROOT = HERE.parent  # voice_agent 目录


def main():
    sys.path.insert(0, str(ROOT))
    os.chdir(ROOT)  # 与 run_src_voice_agent.cmd 的 cd /d %~dp0 一致(配置相对路径)
    from opencode_fastpath import hook
    mode = os.environ.get("OPENCODE_FASTPATH", "off")
    hook.install()
    fp = hook.get_fp()
    print(f"[OPENCODE] fastpath mode={mode}  entries={len(fp.entries) if fp else 0}"
          f"  table={fp.table_path if fp else '-'}", flush=True)
    import voice_agent
    return voice_agent.main()


if __name__ == "__main__":
    sys.exit(main() or 0)
